def salvar_lote_no_banco(lista_tuplas):
    """lista_tuplas: [(chave_casulo, categoria, estacao, quantidade), ...],
    já filtrada só com quantidade > 0. Substitui TODO o estoque no banco.
    Grava em blocos de 500 linhas por vez (bem mais rápido que uma linha por
    vez, que era o gargalo mais provável em bases com milhares de casulos).
    Retorna: True (salvou), False (banco configurado mas falhou), None (banco não configurado)."""
    conn = obter_conexao_bd()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM estoque_casulo")
            tamanho_bloco = 500
            for i in range(0, len(lista_tuplas), tamanho_bloco):
                bloco = lista_tuplas[i:i + tamanho_bloco]
                marcadores = ", ".join(["(%s, %s, %s, %s, now())"] * len(bloco))
                valores_achatados = [valor for tupla in bloco for valor in tupla]
                cur.execute(
                    f"INSERT INTO estoque_casulo (chave_casulo, categoria_peca, estacao, quantidade, atualizado_em) VALUES {marcadores}",
                    valores_achatados
                )
        conn.commit()
        conn.close()
        return True
    except Exception as e:
        try:
            conn.close()
        except Exception:
            pass
        st.session_state.ultimo_erro_bd = str(e)
        return False

# ==========================================
# SENHA COM HASH (sem depender de biblioteca externa)
# ==========================================
def gerar_hash_senha(senha_texto_puro):
    """PBKDF2-HMAC-SHA256 com salt aleatório — não precisa de bcrypt/passlib,
    só o que já vem no Python padrão."""
    salt = os.urandom(16)
    hash_bytes = hashlib.pbkdf2_hmac('sha256', senha_texto_puro.encode('utf-8'), salt, 200_000)
    return binascii.hexlify(salt).decode() + ':' + binascii.hexlify(hash_bytes).decode()

def verificar_senha(senha_texto_puro, hash_armazenado):
    try:
        salt_hex, hash_hex = hash_armazenado.split(':')
        salt = binascii.unhexlify(salt_hex)
        hash_esperado = binascii.unhexlify(hash_hex)
        hash_calculado = hashlib.pbkdf2_hmac('sha256', senha_texto_puro.encode('utf-8'), salt, 200_000)
        return hmac.compare_digest(hash_calculado, hash_esperado)
    except Exception:
        return False

